#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, c;
    cin >> a >> b >> c;

    int n = max({a, b, c});
    vector<long long> fact(n + 1), invFact(n + 1);

    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto countWays = [&](int x, int y) {
        long long result = 0;
        for (int i = 0; i <= min(x, y); ++i) {
            long long term = fact[x] * fact[y] % MOD;
            term = term * invFact[x - i] % MOD;
            term = term * invFact[y - i] % MOD;
            term = term * invFact[i] % MOD;
            result = (result + term) % MOD;
        }
        return result;
    };

    long long answer = countWays(a, b);
    answer = answer * countWays(a, c) % MOD;
    answer = answer * countWays(b, c) % MOD;

    cout << answer << '\n';
    return 0;
}

